/**
 * App component
 *
 * Root of the portfolio application.
 *
 * ── How to customise ──────────────────────────────────────────
 * 1. Update siteProps below with your real name, email, and social handles.
 * 2. Add / edit projects in src/data/projects.js — no changes needed here.
 * ──────────────────────────────────────────────────────────────
 */

import React from "react";

import Header from "./Components/Header";
import Home from "./Components/Home";
import Services from "./Components/Services";
import Portfolio from "./Components/Portfolio";
import Testimonials from "./Components/Testimonials";
import Skills from "./Components/Skills";
import About from "./Components/About";
import Footer from "./Components/Footer";
import heroImage from "./images/profile/kaleem-hero.png";

import "./styles.css";

/**
 * Update the values below with your own information.
 * Leave a field as an empty string ("") to hide that link.
 */
const siteProps = {
  name: "Kaleem",
  title: "Android Developer",
  heroImage,
  email: "Kaleem04.dev@gmail.com",   // ← replace with your real email
  gitHub: "kaleem04",            // ← your GitHub username
  linkedIn: "kaleem-ullah04",
  X : "kaleemdeveloper",                  // ← your LinkedIn profile slug, or ""
};

const App = () => {
  return (
    <div id="main">
      <Header />
      <Home
        name={siteProps.name}
        title={siteProps.title}
        email={siteProps.email}
        profileImage={siteProps.heroImage}
      />
      <Services />
      <Portfolio />
      <Testimonials />
      <Skills />
      <About />
      <Footer
        name={siteProps.name}
        email={siteProps.email}
        gitHub={siteProps.gitHub}
        linkedIn={siteProps.linkedIn}
        X={siteProps.X}
      />
    </div>
  );
};

export default App;

