import React from "react";
import testimonials from "../data/testimonials";

const Testimonials = () => {
  return (
    <section id="testimonials" className="section testimonials">
      <div className="container">
        <p className="section-label">Client Feedback</p>
        <h2 className="section-title">Testimonials</h2>
        <p className="section-subtitle">
          Real reviews from clients I have worked with across product launches,
          refactors, and Play Store releases.
        </p>

        <div className="testimonials-grid">
          {testimonials.map((item) => (
            <article className="testimonial-card" key={`${item.name}-${item.company}`}>
              <p className="testimonial-rating" aria-label={`${item.rating} out of 5 stars`}>
                {"★".repeat(item.rating)}
              </p>
              <p className="testimonial-quote">&ldquo;{item.quote}&rdquo;</p>
              <div className="testimonial-meta">
                <h3>{item.name}</h3>
                <p>
                  {item.role} · {item.company}
                </p>
                <span>{item.project}</span>
              </div>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
};

export default Testimonials;
