/**
 * Portfolio / Projects component
 *
 * Renders data-driven project cards from src/data/projects.js.
 * To add or edit projects, update that file — no code changes needed here.
 */
import React from "react";
import projects from "../data/projects";

const getAssetSrc = (asset) => {
  if (!asset) return "";
  if (typeof asset === "string") return asset;
  if (typeof asset === "object") {
    if (typeof asset.src === "string") return asset.src;
    if (typeof asset.default === "string") return asset.default;
    if (asset.default && typeof asset.default === "object") {
      if (typeof asset.default.src === "string") return asset.default.src;
    }
  }
  return "";
};

const ProjectCard = ({ title, description, tags, github, playStore, apk, demo, screenshot, screenshots }) => {
  const screenshotSrc = getAssetSrc(screenshot);
  const normalizedScreenshots = Array.isArray(screenshots)
    ? screenshots.map(getAssetSrc).filter(Boolean)
    : [];
  const gallery = normalizedScreenshots.length > 0 ? normalizedScreenshots : screenshotSrc ? [screenshotSrc] : [];

  return (
    <div className="project-card">
      {gallery.length > 0 && (
        <div className="project-media-scroll" role="region" aria-label={`${title} screenshots`} tabIndex={0}>
          <div className="project-media-track">
            {gallery.map((src, index) => (
              <img
                key={`${title}-shot-${index}`}
                src={src}
                alt={`${title} screenshot ${index + 1}`}
                className="project-media-image"
                loading="lazy"
                decoding="async"
              />
            ))}
          </div>
        </div>
      )}
      <h3>{title}</h3>
      <p>{description}</p>

    <div className="project-tags">
      {tags.map((tag) => (
        <span className="tag" key={tag}>
          {tag}
        </span>
      ))}
    </div>

      <div className="project-links">
        {github && (
          <a href={github} target="_blank" rel="noopener noreferrer" className="btn btn-outline btn-sm">
            GitHub
          </a>
        )}
        {playStore && (
          <a href={playStore} target="_blank" rel="noopener noreferrer" className="btn btn-primary btn-sm">
            Play Store
          </a>
        )}
        {apk && (
          <a href={apk} target="_blank" rel="noopener noreferrer" className="btn btn-outline btn-sm">
            Download APK
          </a>
        )}
        {demo && (
          <a href={demo} target="_blank" rel="noopener noreferrer" className="btn btn-outline btn-sm">
            Demo ▶
          </a>
        )}
      </div>
    </div>
  );
};

const Portfolio = () => {
  return (
    <section id="projects" className="section projects">
      <div className="container">
        <p className="section-label">My Work</p>
        <h2 className="section-title">Featured Projects</h2>
        <p className="section-subtitle">
          A selection of Android apps I&apos;ve designed, architected, and shipped.
        </p>

        <div className="projects-grid">
          {projects.map((project) => (
            <ProjectCard key={project.title} {...project} />
          ))}
        </div>
      </div>
    </section>
  );
};

export default Portfolio;

